record ApiContract(String description, Predicate<Map<String, Object>> expectedShape) {
    void verify(Map<String, Object> actualResponse) {
        if (!expectedShape.test(actualResponse)) {
            throw new AssertionError("Naruszenie kontraktu: " + description);
        }
    }
}

ApiContract PRODUCT_CONTRACT = new ApiContract(
        "Produkt musi miec id (String), price (Number), inStock (Boolean)",
        response -> response.get("id") instanceof String
                 && response.get("price") instanceof Number
                 && response.get("inStock") instanceof Boolean);

// Strona konsumenta - weryfikacja na stubie uzywanym w WireMock
Map<String, Object> stubbedResponse = Map.of("id", "P1", "price", 199.99, "inStock", true);
PRODUCT_CONTRACT.verify(stubbedResponse);

// Strona dostawcy - weryfikacja na prawdziwym, dzialajacym serwerze
HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
Map<String, Object> actualBody = parseSimpleJson(response.body());
PRODUCT_CONTRACT.verify(actualBody);

Map<String, Object> brokenResponse = Map.of("id", "P1", "price", 199.99); // brak "inStock"
try {
    PRODUCT_CONTRACT.verify(brokenResponse);
} catch (AssertionError e) {
    System.out.println("Wykryto regresje: " + e.getMessage());
}

